import{F as n}from"./chunks/FigureContainer.VL3Ntwlh.js";/* empty css                                                             */import{c as p,o as e,d as a,b as t}from"./chunks/vitepress-theme-teek.VWKGyrHm.js";/* empty css                                                                               */const u=JSON.parse('{"title":"温度系数与Top-p：掌控大模型的创造力开关","description":"深度解读大模型 API 最核心的两个采样参数：Temperature 通过缩放 logits 调节概率分布陡峭度（低温保守、高温奔放），Top-p（核采样）以动态累积概率阈值裁剪长尾候选集。涵盖数学原理、交互效应、场景选型与调参最佳实践。","frontmatter":{"date":"2026-06-29T09:51:34.000Z","title":"温度系数与Top-p：掌控大模型的创造力开关","aliases":["Temperature","Top-p"],"tldr":"Temperature 控概率分布陡峭度，Top-p 动态裁剪候选集——两个参数共同决定模型创造力。","description":"深度解读大模型 API 最核心的两个采样参数：Temperature 通过缩放 logits 调节概率分布陡峭度（低温保守、高温奔放），Top-p（核采样）以动态累积概率阈值裁剪长尾候选集。涵盖数学原理、交互效应、场景选型与调参最佳实践。","tags":["概念","Temperature","Top-P","采样","LLM"],"categories":["大模型基础","推理与生成"],"permalink":"/llm-basic/temperature-top-p"},"headers":[],"relativePath":"llm-basic/temperature-top-p.md","filePath":"22.大模型基础/04.推理与生成/04.温度系数与Top-p.md"}'),l={name:"llm-basic/temperature-top-p.md"},h=Object.assign(l,{setup(r){return(i,s)=>(e(),p("div",null,[s[0]||(s[0]=a(`<h1 id="温度系数与top-p-掌控大模型的创造力开关" tabindex="-1">温度系数与Top-p：掌控大模型的创造力开关 <a class="header-anchor" href="#温度系数与top-p-掌控大模型的创造力开关" aria-label="Permalink to “温度系数与Top-p：掌控大模型的创造力开关”">​</a></h1><blockquote><p><strong>摘要</strong>: Temperature 和 Top-p 是大语言模型 API 中最常用也最容易被误解的两个采样参数，它们共同决定了模型输出的随机性程度。Temperature 在 Softmax 之前对 logits 进行缩放：低温（&lt;1）放大高概率 token 的优势，使输出趋于确定和保守；高温（&gt;1）压缩概率差异，使低概率 token 获得更多采样机会。Top-p（核采样）则从另一个维度控制多样性——只从累积概率达到阈值 p 的最小候选集中采样，动态过滤掉长尾噪声。本文从数学原理出发，通过概率分布可视化直观展示两者的作用机制与交互效应，并结合创意写作、代码生成、事实问答等典型场景给出参数选型矩阵与调参优先级建议，帮助开发者在可控性与创造性之间找到最优平衡点。</p></blockquote><h2 id="_1-核心概念速览" tabindex="-1">1. 核心概念速览 <a class="header-anchor" href="#_1-核心概念速览" aria-label="Permalink to “1. 核心概念速览”">​</a></h2><p>在调用大模型 API 时，<strong>Temperature（温度系数）</strong>和 <strong>Top-p（核采样）</strong> 是两个最常用、也最容易被误解的参数。它们共同决定了模型输出是&quot;保守确定&quot;还是&quot;天马行空&quot;。</p><blockquote><p><strong>官方建议</strong>：通常调整 Temperature <strong>或</strong> Top-p 其中之一即可，不建议同时大幅调整两者。</p></blockquote><table tabindex="0"><thead><tr><th>参数</th><th>作用机制</th><th>值域</th><th>默认值</th><th>一句话总结</th></tr></thead><tbody><tr><td><strong>Temperature</strong></td><td>在 Softmax 之前缩放 Logits，改变概率分布的「陡峭程度」。</td><td>0 ~ 2</td><td>1</td><td>低温保守，高温奔放</td></tr><tr><td><strong>Top-p</strong></td><td>只从累计概率达到 p 的最小候选集中采样，动态裁剪长尾<br><br><strong>Top-p（最高累加概率，Top Cumulative Probability）：</strong>为防止模型选择长尾词，需要一个方式将这些离谱的词过滤掉。<br><br><strong>Top-p 像是一个动态的入围门槛，主要用来切断尾部那些不靠谱的<strong><strong>长尾词</strong></strong>。</strong></td><td>0 ~ 1</td><td>1</td><td>概率阈值，自适应候选集大小</td></tr></tbody></table><h2 id="_2-temperature-温度系数-详解" tabindex="-1">2. Temperature（温度系数）详解 <a class="header-anchor" href="#_2-temperature-温度系数-详解" aria-label="Permalink to “2. Temperature（温度系数）详解”">​</a></h2><h3 id="_2-1-前置概念-logits-与-softmax" tabindex="-1">2.1 前置概念：Logits 与 Softmax <a class="header-anchor" href="#_2-1-前置概念-logits-与-softmax" aria-label="Permalink to “2.1 前置概念：Logits 与 Softmax”">​</a></h3><p>要理解 Temperature，必须先理解两个概念：</p><p>1、<strong>Logits（原始得分）</strong>：模型最后一层（LM Head）直接输出的原始数值，未经任何归一化。分数越高的 token，模型越倾向于选择它。</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>假设词表有 5 个候选词，模型输出的 Logits：</span></span>
<span class="line"><span>&quot;变革&quot;  8.3</span></span>
<span class="line"><span>&quot;改变&quot;  7.1</span></span>
<span class="line"><span>&quot;变化&quot;  5.2</span></span>
<span class="line"><span>&quot;改革&quot;  3.8</span></span>
<span class="line"><span>&quot;修饰&quot; -2.1</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>Logits 只是分数，不是概率——它们加起来不等于 1，并且可能有负数。</p><p>2、<strong>Softmax（归一化指数函数）</strong>：将任意一组实数转换为概率分布（所有值在 0~1 之间，总和为 1）。</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Softmax 的计算过程（以&quot;变革&quot;为例）：</span></span>
<span class="line"><span>1. 对每个 Logits 求指数：e^8.3, e^7.1, e^5.2, e^3.8, e^-2.1</span></span>
<span class="line"><span>2. 把这些指数值加起来作为分母</span></span>
<span class="line"><span>3. 每个 token 的指数值 ÷ 分母 = 该 token 的概率</span></span>
<span class="line"><span></span></span>
<span class="line"><span>结果：</span></span>
<span class="line"><span>&quot;变革&quot;  0.62  ← 分数最高，概率也最高</span></span>
<span class="line"><span>&quot;改变&quot;  0.21</span></span>
<span class="line"><span>&quot;变化&quot;  0.08</span></span>
<span class="line"><span>&quot;改革&quot;  0.03</span></span>
<span class="line"><span>&quot;修饰&quot;  0.00</span></span>
<span class="line"><span>─────────────────</span></span>
<span class="line"><span>合计    1.00</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br></div></div><h3 id="_2-2-temperature-的数学原理" tabindex="-1">2.2 Temperature 的数学原理 <a class="header-anchor" href="#_2-2-temperature-的数学原理" aria-label="Permalink to “2.2 Temperature 的数学原理”">​</a></h3><p>Temperature 在 Softmax <strong>之前</strong>对所有 Logits 进行缩放：</p>`,16)),t(n,{type:"image",content:"https://insight-stack-1252300811.cos.ap-shanghai.myqcloud.com/img/llm-basic/llm-concept/llm_input_output.png",caption:""}),s[1]||(s[1]=a(`<p>极其简单的公式，但效果极其显著：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>T = 0.5（低温）：</span></span>
<span class="line"><span>  Logits ÷ 0.5 = [16.6, 14.2, 10.4, 7.6, -4.2]  ← 差距被放大 2 倍</span></span>
<span class="line"><span>  Softmax       = [0.99, 0.01, 0.00, 0.00, 0.00]</span></span>
<span class="line"><span>  → 概率极度集中在最高分 token，输出确定、保守、一板一眼</span></span>
<span class="line"><span></span></span>
<span class="line"><span>T = 1.0（标准温度）：</span></span>
<span class="line"><span>  Logits ÷ 1.0 → 走标准 Softmax，概率分布保持原始比例</span></span>
<span class="line"><span>  → 模型&quot;本色出演&quot;，依赖训练时的统计模式</span></span>
<span class="line"><span></span></span>
<span class="line"><span>T = 2.0（高温）：</span></span>
<span class="line"><span>  Logits ÷ 2.0 = [4.15, 3.55, 2.60, 1.90, -1.05]  ← 差距被压缩</span></span>
<span class="line"><span>  Softmax       = [0.42, 0.30, 0.17, 0.10, 0.01]</span></span>
<span class="line"><span>  → 概率分布趋于平坦，低分 token 也有不小概率被选中，输出更多样、更有创意</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br></div></div><h3 id="_2-3-temperature-的直观理解" tabindex="-1">2.3 Temperature 的直观理解 <a class="header-anchor" href="#_2-3-temperature-的直观理解" aria-label="Permalink to “2.3 Temperature 的直观理解”">​</a></h3><p>可以把 T 理解为 <strong>「创造力的旋钮」</strong>：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Prompt: &quot;今天天气真&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>T ≈ 0 (贪婪):  &quot;今天天气真好！阳光明媚，万里无云。&quot;         ← 最确定</span></span>
<span class="line"><span>T = 0.3:       &quot;今天天气真好！适合出去走走。&quot;                ← 比较确定</span></span>
<span class="line"><span>T = 0.7:       &quot;今天天气真不错，不如去公园散步吧。&quot;             ← 适度多样</span></span>
<span class="line"><span>T = 1.0:       &quot;今天天气真适合喝一杯热咖啡然后躺在沙发上看书。&quot;  ← 有创意</span></span>
<span class="line"><span>T = 1.5:       &quot;今天天气真相是某种不可言说的隐喻。&quot;             ← 开始离谱</span></span>
<span class="line"><span>T = 2.0:       &quot;今天天气真旮旯三才图会...&quot;                   ← 完全随机</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><h3 id="_2-4-不同场景的推荐值" tabindex="-1">2.4 不同场景的推荐值 <a class="header-anchor" href="#_2-4-不同场景的推荐值" aria-label="Permalink to “2.4 不同场景的推荐值”">​</a></h3><table tabindex="0"><thead><tr><th>Temperature</th><th>效果</th><th>适用场景</th></tr></thead><tbody><tr><td>0 ~ 0.3</td><td>高度确定，几乎每次输出相同</td><td>代码生成、数学推理、事实问答、翻译</td></tr><tr><td>0.4 ~ 0.7</td><td>自然且有适度变化</td><td>日常对话、客服、摘要</td></tr><tr><td>0.8 ~ 1.2</td><td>富有创意，词汇多变</td><td>创意写作、头脑风暴、文案生成</td></tr><tr><td>1.3 ~ 1.5</td><td>开始出现不合逻辑的内容</td><td>一般不推荐常规任务使用</td></tr><tr><td>&gt; 1.5</td><td>输出质量急剧下降</td><td>几乎不使用</td></tr></tbody></table><h2 id="_3-top-p-核采样-详解" tabindex="-1">3. Top-p（核采样）详解 <a class="header-anchor" href="#_3-top-p-核采样-详解" aria-label="Permalink to “3. Top-p（核采样）详解”">​</a></h2><h3 id="_3-1-为什么需要-top-p" tabindex="-1">3.1 为什么需要 Top-p？ <a class="header-anchor" href="#_3-1-为什么需要-top-p" aria-label="Permalink to “3.1 为什么需要 Top-p？”">​</a></h3><p>在介绍 Top-p 之前，先看它的前身 <strong>Top-k 采样</strong>，Top-k 的思路很简单：只从概率最高的 <strong>k 个</strong>候选 token 中随机采样，切断长尾的低概率&quot;噪音&quot;。</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>原始概率分布（词表大小 ~50000）：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  &quot;好的&quot;  ████████████████████  0.40</span></span>
<span class="line"><span>  &quot;可以&quot;  ██████████            0.20</span></span>
<span class="line"><span>  &quot;没问题&quot; ██████               0.12</span></span>
<span class="line"><span>  &quot;行&quot;    ████                 0.08</span></span>
<span class="line"><span>  &quot;嗯&quot;    ███                  0.06</span></span>
<span class="line"><span>  &quot;OK&quot;    ██                   0.05</span></span>
<span class="line"><span>  &quot;好滴&quot;  ██                   0.04</span></span>
<span class="line"><span>  ... (49993 个低概率 token) ...</span></span>
<span class="line"><span>  &quot;旮旯&quot;  ▏                    0.00001</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Top-k (k=6): 只从前 6 个候选里按概率采样</span></span>
<span class="line"><span>  → 重归一化后：&quot;好的&quot; 44%, &quot;可以&quot; 22%, &quot;没问题&quot; 13%, &quot;行&quot; 9%, &quot;嗯&quot; 7%, &quot;OK&quot; 5%</span></span>
<span class="line"><span>  → 从这 6 个中随机抽取一个</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br></div></div><p><strong>Top-k 的问题</strong>：固定的 k 值对不同语境不够灵活。</p><ul><li>一个很确定的上下文（如 <code>&quot;法国的首都是&quot;</code>）可能只有 2-3 个合理 token，k=50 会引入噪音</li><li>一个开放的上下文（如 <code>&quot;我认为&quot;</code>）可能有 50+ 个合理选择，k=10 会过度限制创造力</li></ul><h3 id="_3-2-top-p-的工作机制" tabindex="-1">3.2 Top-p 的工作机制 <a class="header-anchor" href="#_3-2-top-p-的工作机制" aria-label="Permalink to “3.2 Top-p 的工作机制”">​</a></h3><p>Top-p（Nucleus Sampling，核采样）解决了 Top-k 固定候选数的问题：<strong>不固定取 k 个，而是动态选取累计概率达到阈值 p 的最小候选集</strong>。</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Top-p (p=0.9) 的工作方式：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  概率分布（从高到低排序）：</span></span>
<span class="line"><span>  &quot;好的&quot;      0.40  ← 纳入，累计 0.40</span></span>
<span class="line"><span>  &quot;可以&quot;      0.25  ← 纳入，累计 0.65</span></span>
<span class="line"><span>  &quot;没问题&quot;    0.12  ← 纳入，累计 0.77</span></span>
<span class="line"><span>  &quot;行&quot;        0.08  ← 纳入，累计 0.85</span></span>
<span class="line"><span>  &quot;嗯&quot;        0.06  ← 纳入，累计 0.91  ← 累计超过 0.9，停止！</span></span>
<span class="line"><span>  -------- 阈值 ----------</span></span>
<span class="line"><span>  &quot;OK&quot;        0.04  ← 丢弃</span></span>
<span class="line"><span>  &quot;好滴&quot;      0.03  ← 丢弃</span></span>
<span class="line"><span>  ... 其余全部丢弃 ...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  在入围的 5 个 token 中按原概率重归一化后采样</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br></div></div><p><strong>直观类比</strong>：想象你在点外卖。Top-k 是说&quot;只看评分前 20 的餐厅&quot;；Top-p 是说&quot;只考虑能覆盖 90% 好评的餐厅&quot;。后者的候选集大小会根据地区（语境）自动调整——美食街可能有 50 家入围，偏远地区可能只有 3 家。</p><h3 id="_3-3-p-值的调参指南" tabindex="-1">3.3 p 值的调参指南 <a class="header-anchor" href="#_3-3-p-值的调参指南" aria-label="Permalink to “3.3 p 值的调参指南”">​</a></h3><table tabindex="0"><thead><tr><th>p 值</th><th>效果</th><th>适用场景</th></tr></thead><tbody><tr><td>0.9 ~ 1.0</td><td>高多样性，更有创意</td><td>创意写作、头脑风暴</td></tr><tr><td>0.7 ~ 0.9</td><td>平衡</td><td>通用对话</td></tr><tr><td>0.5 ~ 0.7</td><td>更保守，更确定</td><td>事实性问答、代码生成</td></tr></tbody></table><h3 id="_3-4-top-p-与-top-k-的联用" tabindex="-1">3.4 Top-p 与 Top-k 的联用 <a class="header-anchor" href="#_3-4-top-p-与-top-k-的联用" aria-label="Permalink to “3.4 Top-p 与 Top-k 的联用”">​</a></h3><p>现代 LLM 推理中，<strong>Top-p + Top-k 经常联用</strong>：<strong>先用 Top-k 粗筛（砍掉明显不合理的极低概率 token），再用 Top-p 精筛（根据语境自适应裁剪）。</strong></p><h2 id="_4-temperature-vs-top-p-对比与协同" tabindex="-1">4. Temperature vs Top-p：对比与协同 <a class="header-anchor" href="#_4-temperature-vs-top-p-对比与协同" aria-label="Permalink to “4. Temperature vs Top-p：对比与协同”">​</a></h2><h3 id="_4-1-核心区别" tabindex="-1">4.1 核心区别 <a class="header-anchor" href="#_4-1-核心区别" aria-label="Permalink to “4.1 核心区别”">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>Temperature</th><th>Top-p</th></tr></thead><tbody><tr><td><strong>作用位置</strong></td><td>Softmax 之前（改变 Logits）</td><td>Softmax 之后（裁剪概率分布）</td></tr><tr><td><strong>调节方式</strong></td><td>连续缩放整个分布</td><td>设置累积概率阈值</td></tr><tr><td><strong>候选集大小</strong></td><td>不变（始终是整个词表）</td><td>动态变化（依语境自适应）</td></tr><tr><td><strong>对高频词的影响</strong></td><td>低温→放大，高温→抑制</td><td>低频词可能被完全剪掉</td></tr><tr><td><strong>对低频词的影响</strong></td><td>永远保留（只是概率变小）</td><td>可能被直接排除在外</td></tr></tbody></table><h3 id="_4-2-组合效果" tabindex="-1">4.2 组合效果 <a class="header-anchor" href="#_4-2-组合效果" aria-label="Permalink to “4.2 组合效果”">​</a></h3><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Temperature + Top-p 的组合：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>T=0.2, p=0.9:</span></span>
<span class="line"><span>  → 分布高度集中，再从 90% 概率质量中采样</span></span>
<span class="line"><span>  → 结果：极度保守，多样性很低</span></span>
<span class="line"><span></span></span>
<span class="line"><span>T=1.2, p=0.5:</span></span>
<span class="line"><span>  → 分布趋于平坦，但只从 50% 概率质量中采样（裁剪了后半部分）</span></span>
<span class="line"><span>  → 结果：中等多样性，但候选集较小</span></span>
<span class="line"><span></span></span>
<span class="line"><span>T=1.2, p=0.95:</span></span>
<span class="line"><span>  → 分布趋于平坦，且几乎不裁剪</span></span>
<span class="line"><span>  → 结果：高多样性，最具创造力</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br></div></div><p>这就是为什么 OpenAI 官方建议不要同时调整两者——两个参数的交织效果不容易直观预判。通常先选一个调，另一个保持默认值即可。</p><h2 id="_5-最佳实践总结" tabindex="-1">5. 最佳实践总结 <a class="header-anchor" href="#_5-最佳实践总结" aria-label="Permalink to “5. 最佳实践总结”">​</a></h2><h3 id="_6-1-调参原则" tabindex="-1">6.1 调参原则 <a class="header-anchor" href="#_6-1-调参原则" aria-label="Permalink to “6.1 调参原则”">​</a></h3><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>调参决策树：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>需要精确、一致的结果？</span></span>
<span class="line"><span>├─ 是 → 代码/数学/翻译 → T=0, p=1（或不指定）</span></span>
<span class="line"><span>└─ 否 → 需要创意程度？</span></span>
<span class="line"><span>    ├─ 高创意 → 写作/头脑风暴 → T=0.8~1.2, p=0.9~0.95</span></span>
<span class="line"><span>    ├─ 中等 → 日常对话/客服 → T=0.5~0.8, p=1（或不指定）</span></span>
<span class="line"><span>    └─ 低 → 事实性问答/摘要 → T=0.1~0.3, p=1（或不指定）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><h3 id="_6-2-常见误区" tabindex="-1">6.2 常见误区 <a class="header-anchor" href="#_6-2-常见误区" aria-label="Permalink to “6.2 常见误区”">​</a></h3><table tabindex="0"><thead><tr><th>误区</th><th>真相</th></tr></thead><tbody><tr><td>&quot;T=0 就一定完全确定&quot;</td><td><strong>受浮点精度、硬件差异影响，可能仍有微小随机性</strong></td></tr><tr><td>&quot;Top-p 越大越好&quot;</td><td>p=1 时所有 token 都可能被选中，包括低概率噪音</td></tr><tr><td>&quot;同时调小 T 和 p 效果最好&quot;</td><td>可能过度限制，输出单调重复</td></tr><tr><td>&quot;T 和 p 是同一类参数&quot;</td><td>T 在 Softmax 前缩放 Logits，p 在 Softmax 后裁剪分布，机制完全不同</td></tr></tbody></table>`,32))]))}});export{u as __pageData,h as default};
